  PRIMARY KEY (`id`),
  KEY `idx_pch_pump` (`pump_id`),
  KEY `idx_pch_station` (`station_id`),
  KEY `fk_pump_calibration_history_performed_by` (`performed_by`),
  CONSTRAINT `fk_pump_calibration_history_performed_by` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pump_calibration_history_pump_id` FOREIGN KEY (`pump_id`) REFERENCES `fuel_pumps` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pump_calibration_history_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------------
-- Table: `pump_configuration`
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `pump_configuration`;
CREATE TABLE `pump_configuration` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `pump_number` varchar(10) NOT NULL,
  `fuel_type` varchar(100) NOT NULL,
  `pump_status` enum('active','inactive','maintenance') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_station_pump` (`station_id`,`pump_number`),
  UNIQUE KEY `unique_station_fuel_pump` (`station_id`,`fuel_type`),
  KEY `idx_station_fuel` (`station_id`,`fuel_type`),
  KEY `idx_pump_status` (`pump_status`),
  CONSTRAINT `fk_pump_configuration_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: `purchase_order_items`
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `purchase_order_items`;
CREATE TABLE `purchase_order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `item_name` varchar(255) NOT NULL,
