  `shift_name` varchar(100) NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `shift_key` (`shift_key`),
  KEY `idx_shift_key` (`shift_key`),
  KEY `idx_active_sort` (`is_active`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: `shift_reports`
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `shift_reports`;
CREATE TABLE `shift_reports` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `report_date` date NOT NULL,
  `shift` enum('AM','PM','Night') NOT NULL DEFAULT 'AM',
  `status` enum('open','pending_verification','finalized') NOT NULL DEFAULT 'open',
  `created_by` int(11) NOT NULL,
