  KEY `fk_shift_creator` (`created_by`),
  KEY `fk_shift_finalizer` (`finalized_by`),
  CONSTRAINT `fk_shift_reports_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_shift_reports_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- -----------------------------------------------------------
-- Table: `shifts`
