  KEY `idx_status` (`status`),
  KEY `idx_event_type` (`event_type_id`),
  CONSTRAINT `staff_calendar_events_ibfk_1` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`),
  CONSTRAINT `staff_calendar_events_ibfk_2` FOREIGN KEY (`event_type_id`) REFERENCES `staff_event_types` (`id`),
  CONSTRAINT `staff_calendar_events_ibfk_3` FOREIGN KEY (`staff_encoder_id`) REFERENCES `users` (`id`),
  CONSTRAINT `staff_calendar_events_ibfk_4` FOREIGN KEY (`manager_assigned_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- -----------------------------------------------------------
