-- -----------------------------------------------------------
-- Table: `station_inventory`
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `station_inventory`;
CREATE TABLE `station_inventory` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
