  CONSTRAINT `fk_station_inventory_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=2660 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



-- -----------------------------------------------------------
-- Table: `station_items`
