-- -----------------------------------------------------------
-- Table: `suspicious_activity_alerts`
-- -----------------------------------------------------------
DROP TABLE IF EXISTS `suspicious_activity_alerts`;
CREATE TABLE `suspicious_activity_alerts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `activity_type` varchar(100) DEFAULT NULL COMMENT 'multiple_failed_logins, unusual_access_pattern, data_exfiltration',
